// (X) One atomic per thread
__global__ void reduce_atomic_per_thread(const float* x, float* out, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) atomicAdd(&out[0], x[i]);
}

// (Y) Block-local tree reduction + one atomic per block
__global__ void reduce_block_then_atomic(const float* x, float* out, int N) {
    __shared__ float smem[256];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + tid;
    smem[tid] = (i < N) ? x[i] : 0.0f;
    __syncthreads();
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) smem[tid] += smem[tid + s];
        __syncthreads();
    }
    if (tid == 0) atomicAdd(&out[0], smem[0]);
}
